import os, random, shutil, subprocess, sys
CBL='/app/src/program.cbl'; PY='/app/program.py'
def gen_accounts(rng):
    out=[]
    for _ in range(rng.randint(0,5)):
        i=rng.choice(['U001','U002','U003','U004'])
        out.append(i+(''.join(rng.choice('ABC def') for _ in range(20)))+('%010d'%rng.choice([0,100,1180,1800,9999999999,rng.randint(0,9999999999)])))
    return ''.join(out).encode()
def gen_books(rng):
    out=[]
    for _ in range(rng.randint(0,5)):
        out.append(rng.choice(['B001','B002','B003'])+''.join(rng.choice('XYZ abc') for _ in range(20))+rng.choice(['U001','U002','U003']))
    return ''.join(out).encode()
def gen_trans(rng):
    return b''.join(rng.choice(['B001','B002'])+('%010d'%rng.randint(0,9999999999))+rng.choice(['U001','U002'])+rng.choice(['U001','U002']) for _ in range(rng.randint(0,3))).encode() if False else b''.join((rng.choice(['B001','B002'])+('%010d'%rng.randint(0,9999999999))+rng.choice(['U001','U002'])+rng.choice(['U001','U002'])).encode() for _ in range(rng.randint(0,3)))
def gen_input(rng):
    b=rng.choice(['U001','U002','U003','U004']); s=rng.choice(['U001','U002','U003','U004']); k=rng.choice(['B001','B002','B003'])
    amt='%010d'%rng.randint(0,9999999999)
    if rng.random()<0.5: amt=''.join(c if rng.random()<0.7 else ' ' for c in amt)
    rec=(b+s+k+amt).encode()
    if rng.random()<0.3: rec=rec[:rng.randint(1,len(rec))]
    return rec
def run(idx,rng):
    root=f'/tmp/fz2/c{idx}'; shutil.rmtree(root,ignore_errors=True); os.makedirs(root+'/src'); os.makedirs(root+'/data')
    shutil.copy(CBL,root+'/src/program.cbl'); shutil.copy(PY,root+'/program.py')
    a=gen_accounts(rng); bk=gen_books(rng); tr=gen_trans(rng)
    if rng.random()<0.4 and a: a=a[:rng.randint(1,len(a)-1)] if len(a)>1 else a
    if rng.random()<0.4 and bk: bk=bk[:rng.randint(1,len(bk)-1)] if len(bk)>1 else bk
    if rng.random()<0.3 and tr: tr=tr[:rng.randint(1,len(tr)-1)] if len(tr)>1 else tr
    open(root+'/data/ACCOUNTS.DAT','wb').write(a); open(root+'/data/BOOKS.DAT','wb').write(bk); open(root+'/data/TRANSACTIONS.DAT','wb').write(tr)
    open(root+'/src/INPUT.DAT','wb').write(gen_input(rng))
    shutil.copytree(root+'/data',root+'/data_init')
    r=subprocess.run(['cobc','-x','-o','prog','src/program.cbl'],cwd=root,capture_output=True)
    if r.returncode: print('compile fail'); return True
    subprocess.run(['./prog'],cwd=root,capture_output=True)
    co={f:open(root+'/data/'+f,'rb').read() for f in ['ACCOUNTS.DAT','BOOKS.DAT','TRANSACTIONS.DAT']}
    shutil.rmtree(root+'/data'); shutil.copytree(root+'/data_init',root+'/data')
    subprocess.run([sys.executable,root+'/program.py'],cwd=root,capture_output=True)
    po={f:open(root+'/data/'+f,'rb').read() for f in co}
    if co!=po:
        print('MISMATCH',idx,'input',open(root+'/src/INPUT.DAT','rb').read())
        for f in co:
            if co[f]!=po[f]: print(' ',f,'\n  co',repr(co[f]),'\n  py',repr(po[f]))
        return False
    return True
rng=random.Random(int(sys.argv[1])); n=int(sys.argv[2]); bad=0
for i in range(n):
    if not run(i,rng):
        bad+=1
        if bad>=6: break
print('done bad',bad)
PYEOF
